// R22 — the equivalence harness for the fetch controller.
//
// One clock, one set of stimulus, two implementations: `FetchFsm` (the M14
// `switch`) and `FetchFsmReference` (the four equality-tested `when` blocks it
// replaces). Both are generated by ScalaHDL; this wrapper is hand-written and
// exists only so one Verilator model contains both, letting the testbench
// compare them cycle by cycle instead of comparing two listings by eye.
//
// Nothing here decides what is correct. It wires, and the C++ testbench
// compares.

module fetch_fsm_equiv(
  input clk,
  input resetn,
  input mem_ready,
  input [31:0] mem_rdata,

  output sw_mem_valid,
  output sw_mem_instr,
  output [31:0] sw_mem_addr,
  output [31:0] sw_instruction,
  output [1:0] sw_state,

  output ref_mem_valid,
  output ref_mem_instr,
  output [31:0] ref_mem_addr,
  output [31:0] ref_instruction,
  output [1:0] ref_state
);

  FetchFsm switch_form(
    .clk(clk),
    .resetn(resetn),
    .mem_ready(mem_ready),
    .mem_rdata(mem_rdata),
    .mem_valid(sw_mem_valid),
    .mem_instr(sw_mem_instr),
    .mem_addr(sw_mem_addr),
    .instruction(sw_instruction),
    .state(sw_state)
  );

  FetchFsmReference when_form(
    .clk(clk),
    .resetn(resetn),
    .mem_ready(mem_ready),
    .mem_rdata(mem_rdata),
    .mem_valid(ref_mem_valid),
    .mem_instr(ref_mem_instr),
    .mem_addr(ref_mem_addr),
    .instruction(ref_instruction),
    .state(ref_state)
  );

endmodule
